                inp_has8 = any(8 in row for row in inp) if isinstance(inp, list) else False
                out_has8 = any(8 in row for row in out) if isinstance(out, list) else False
                print(f"  input: has 8s={inp_has8}, output: has 8s={out_has8}")
                if inp_has8:
                    has8_any = True

        if not has8_any:
            print("  NO 8s found in this file")

# Search for any JSON files with 8s
print("\n\nSearching all JSON files for 8s:")
for f in sorted(os.listdir(programs)):
    if f.endswith('.json'):
        fpath = os.path.join(programs, f)
        with open(fpath) as fh:
            content = json.load(fh)

        def check_for_8(obj, path=""):
            if isinstance(obj, dict):
                return any(check_for_8(v, f"{path}.{k}") for k, v in obj.items())
            elif isinstance(obj, list):
                elem = obj[0] if len(obj) > 0 else None
                if isinstance(elem, list) and 8 in elem:
                    return True
                return any(check_for_8(e, f"{path}.{i}") for i, e in enumerate(obj))
            return False

        if check_for_8(content):
            print(f"  {f}: HAS 8s")
